<div class="section-heading"><div><div class="eyebrow">Catálogo</div><h1>Editar produto</h1></div><a class="btn btn-light" href="/products">Voltar</a></div><div class="card"><div class="card-body"><form method="post" action="/products/<?=(int)$product['id']?>/update"><?php echo \App\Core\CSRF::field();?><div class="row g-3"><div class="col-md-5"><label class="form-label">Produto</label><input class="form-control" name="name" value="<?=htmlspecialchars($product['name'],ENT_QUOTES,'UTF-8')?>" required></div><div class="col-md-3"><label class="form-label">SKU</label><input class="form-control" name="sku" value="<?=htmlspecialchars($product['sku']??'',ENT_QUOTES,'UTF-8')?>"></div><div class="col-md-4"><label class="form-label">Categoria</label><input class="form-control" name="category" value="<?=htmlspecialchars($product['category']??'',ENT_QUOTES,'UTF-8')?>"></div><div class="col-12"><label class="form-label">Descrição</label><textarea class="form-control" name="description" rows="2"><?=htmlspecialchars($product['description']??'',ENT_QUOTES,'UTF-8')?></textarea></div><div class="col-md-3"><label class="form-label">Custo</label><input class="form-control" type="number" step=".01" min="0" name="cost_price" value="<?=htmlspecialchars((string)$product['cost_price'])?>"></div><div class="col-md-3"><label class="form-label">Venda</label><input class="form-control" type="number" step=".01" min="0" name="sale_price" value="<?=htmlspecialchars((string)$product['sale_price'])?>" required></div><?php if($stockEnabled):?><div class="col-md-3"><label class="form-label">Estoque</label><input class="form-control" type="number" step=".001" min="0" name="stock" value="<?=htmlspecialchars((string)$product['stock'])?>"></div><div class="col-md-3"><label class="form-label">Estoque mínimo</label><input class="form-control" type="number" step=".001" min="0" name="minimum_stock" value="<?=htmlspecialchars((string)$product['minimum_stock'])?>"></div><?php endif;?><div class="col-md-3"><label class="form-label">Unidade</label><input class="form-control" name="unit" value="<?=htmlspecialchars($product['unit']??'un')?>"></div><div class="col-md-3"><label class="form-label">Comissão na venda</label><select class="form-select" name="commission_type"><option value="none" <?=($product['commission_type']??'none')==='none'?'selected':''?>>Sem comissão específica</option><option value="percent" <?=($product['commission_type']??'')==='percent'?'selected':''?>>Percentual</option><option value="fixed" <?=($product['commission_type']??'')==='fixed'?'selected':''?>>Valor fixo por unidade</option></select></div><div class="col-md-3"><label class="form-label">Valor da comissão</label><input class="form-control" type="number" step=".01" min="0" name="commission_value" value="<?=htmlspecialchars((string)($product['commission_value']??0))?>"></div><div class="col-md-4 d-flex align-items-end"><label class="form-check"><input class="form-check-input" type="checkbox" name="active" value="1" <?=$product['active']?'checked':''?>> Produto ativo</label></div></div><button class="btn btn-primary mt-4">Salvar produto</button></form></div></div><form class="mt-3" method="post" action="/products/<?=(int)$product['id']?>/deactivate" onsubmit="return confirm('Inativar este produto? O histórico de vendas será preservado.')"><?php echo \App\Core\CSRF::field();?><button class="btn btn-outline-danger">Inativar produto</button></form>
